  floors: [], // raised walkable tops {x0,x1,z0,z1,top}
  glass: [], // {box, mesh, broken}
  sites: {
    A: { x: -21, z: 0, r: 5.6 },
    B: { x: 21, z: 0, r: 5.6 },
