    const def = currentDef(f);
    if (def && def.reload > 0) {
      relP = 1 - w.reloadT / def.reload;
      relBump = Math.sin(Math.PI * clamp01(relP));
      magBump = Math.sin(Math.PI * clamp01((relP - 0.25) / 0.6));
    }
