  S.bomb.site = at;
  S.bomb.planter = c;
  S.bomb.pos = { x: c.pos.x, y: c.pos.y, z: c.pos.z };
  S.bomb.carrier = null;
  c.money = Math.min(MONEY.cap, c.money + MONEY.planterBonus);
